// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function _run(uint256 amount_, uint256 rate_, uint256 duration_, uint256 ltc_) internal {
        vm.assume(true);
        uint256 zeroDuration;
        try c.interestFor(amount_, rate_, 0) returns (uint256 __r) { zeroDuration = __r; } catch { return; }
        uint256 actual;
        try c.interestFor(amount_, rate_, duration_) returns (uint256 __r) { actual = __r; } catch { return; }
        assertTrue(zeroDuration == 0 &&
            actual == ((amount_ * ((rate_ * duration_) / 365 days)) / 1e18));
    }

    function testFuzz_run(uint256 amount_, uint256 rate_, uint256 duration_, uint256 ltc_) public {
        _run(amount_, rate_, duration_, ltc_);
    }

    receive() external payable {}
}
